public class Solution {
  /**
   * 按前缀长度分桶：byLen[len] 这张哈希表的键是"地址的高 len 位"，值是该前缀首次出现的规则下标
   * （并列取更小下标）。查询时从 len=32 往下扫到 0，第一个命中就是最长前缀 —— 至多 33 次哈希查找。
   * 移位两端特判：len==0 时键恒为 0（不能用 >>> 32，因为 int 移位按 32 取模）；
   * len==32 时用 >>> 0；一律用无符号右移 >>>，避免负 int 地址的符号位污染。
   */
  public static int[] nextHopFor(int[] prefixAddrs, int[] prefixLens, int[] targets) {
    if (prefixAddrs.length != prefixLens.length) {
      throw new IllegalArgumentException("prefix arrays must be parallel");
    }
    @SuppressWarnings("unchecked")
    java.util.HashMap<Integer, Integer>[] byLen = new java.util.HashMap[33];
    for (int r = 0; r < prefixAddrs.length; r++) {
      int len = prefixLens[r];
      if (len < 0 || len > 32) throw new IllegalArgumentException("bad prefix length");
      int masked = len == 0 ? 0 : prefixAddrs[r] >>> (32 - len);
      if (byLen[len] == null) byLen[len] = new java.util.HashMap<Integer, Integer>();
      Integer held = byLen[len].get(masked);
      if (held == null || r < held) byLen[len].put(masked, r);   // 并列取更小下标
    }
    int[] out = new int[targets.length];
    for (int q = 0; q < targets.length; q++) {
      int t = targets[q];
      int hit = -1;
      for (int len = 32; len >= 0 && hit < 0; len--) {
        java.util.HashMap<Integer, Integer> table = byLen[len];
        if (table == null) continue;
        Integer got = table.get(len == 0 ? 0 : t >>> (32 - len));
        if (got != null) hit = got;
      }
      out[q] = hit;
    }
    return out;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：按输入顺序线性扫规则，第一条"看起来匹配"的就返回。
  // 两个错：(1) 没有最长前缀优先；(2) >>> (32 - 0) == >>> 32 == >>> 0，默认路由永远不命中。
  public static int[] nextHopFor(int[] prefixAddrs, int[] prefixLens, int[] targets) {
    int[] out = new int[targets.length];
    for (int q = 0; q < targets.length; q++) {
      int t = targets[q];
      out[q] = -1;
      for (int r = 0; r < prefixAddrs.length; r++) {
        int shift = 32 - prefixLens[r];
        if ((t >>> shift) == (prefixAddrs[r] >>> shift)) {
          out[q] = r;
          break;
        }
      }
    }
    return out;
  }
}
